render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, group = cfg$group, y = cfg$y), c("x", "group", "y")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$x, y = cfg$y, fill = cfg$group)) + ggplot2::geom_col(position = "stack") + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = cfg$x, y = cfg$y, fill = cfg$group); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
